(1, 1, 1, 'Premium 5G Flagship Smartphone (256GB / 12GB RAM)', 'premium-5g-smartphone', 'Flagship Octa-Core Snapdragon processor with stunning 120Hz AMOLED display, triple AI 108MP camera array, 5000mAh battery, and 65W SuperDart charging. Experience blazing 5G speed across all Indian carriers.', 54999.00, 64999.00, 15, TRUE, 'https://images.unsplash.com/photo-1598327105666-5b89351aff97?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1511707171634-5f897ff02aa9?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1565849904461-04a58ad377e0?auto=format&fit=crop&w=800&q=80', 4.8, 342, 'Zenith', CURRENT_TIMESTAMP),

