(3, 1, 1, 'RGB Hot-Swappable Mechanical Gaming Keyboard (Tactile Browns)', 'rgb-mechanical-keyboard', 'Aircraft-grade anodized aluminum frame, per-key dynamic RGB backlighting, hot-swappable tactile brown mechanical switches, sound dampening foam, and braided USB-C detachable cable.', 2999.00, 4499.00, 42, TRUE, 'https://images.unsplash.com/photo-1587829741301-dc798b83add3?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1618384887929-16ec33fab9ef?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1595225476474-87563907a212?auto=format&fit=crop&w=800&q=80', 4.7, 185, 'VortexKeys', CURRENT_TIMESTAMP),

